-- Fourth source-backed exact-name plant content batch; blank fields only.
CREATE TEMP TABLE curated_plant_content_fourth (product_code bigint PRIMARY KEY, expected_name text NOT NULL, latin text NOT NULL, short_text text NOT NULL, full_text text NOT NULL, care_text text NOT NULL, light text NOT NULL, watering text NOT NULL, guide_light text NOT NULL, guide_water text NOT NULL) ON COMMIT DROP;
INSERT INTO curated_plant_content_fourth(product_code,expected_name,latin,short_text,full_text,care_text,light,watering,guide_light,guide_water) VALUES
  (50,'Бонсай Citrus Myrtifolia(апельсин)','Citrus × aurantium','Миниатюрное цитрусовое дерево, сформированное как бонсай.','Чинотто, известный в продаже как Citrus myrtifolia, выращивают ради плотной вечнозелёной кроны, ароматных цветков и небольших плодов. Появление плодов зависит от условий содержания.','Поставьте в очень светлое место, защищая от жгучего полуденного солнца. В сезон роста поливайте по мере подсыхания поверхности грунта, без застоя воды; зимой полив сократите. Обеспечьте цитрусовому прохладную светлую зимовку.','sunny','moderate','Поставьте в очень светлое место, защищая от жгучего полуденного солнца.','В сезон роста поливайте по мере подсыхания поверхности грунта, без застоя воды; зимой полив сократите.'),
  (55,'Бонсай Атропурпуреум (Клен японский)','Acer palmatum ''Atropurpureum''','Японский клён с пурпурной листвой в форме бонсай.','Листопадный японский клён меняет окраску листвы в течение сезона. На зиму листья опадают; это нормальный сезонный цикл, а не признак гибели растения.','Держите на открытом воздухе в светлой полутени, защищая листья от палящего полуденного солнца. В сезон роста поливайте, когда верхний слой начинает подсыхать; не пересушивайте маленький горшок. Зимой защищайте корни в контейнере от сильного промерзания.','diffused','frequent','Держите на открытом воздухе в светлой полутени, защищая листья от палящего полуденного солнца.','В сезон роста поливайте, когда верхний слой начинает подсыхать; не пересушивайте маленький горшок.'),
  (57,'Бонсай Зантоксилум','Zanthoxylum','Бонсай из зантоксилума с мелкой ароматной листвой.','Зантоксилумы — древесные растения с ароматной листвой. Точный вид этого экземпляра по торговому названию не определён, поэтому листопадность и плодоношение не обещаем.','Поставьте в светлое место с несколькими часами мягкого солнца. Поливайте после начала подсыхания поверхности хорошо дренированного субстрата; малый объём бонсайного горшка проверяйте регулярно. Режим зимовки зависит от вида.','sunny','moderate','Поставьте в светлое место с несколькими часами мягкого солнца.','Поливайте после начала подсыхания поверхности хорошо дренированного субстрата; малый объём бонсайного горшка проверяйте регулярно.'),
  (62,'Бонсай Кипарис (Chamaecyparis)','Chamaecyparis','Вечнозелёный хвойный бонсай из кипарисовика.','Кипарисовики имеют мелкую чешуевидную хвою и формируются обрезкой. Вид и сорт этого растения в карточке не указаны.','Поставьте на открытом воздухе в светлое место; в комнате постоянное содержание не планируйте. Поливайте после лёгкого подсыхания поверхности субстрата, не допуская полного пересыхания корневого кома. Зимой защитите небольшой контейнер от сильного промерзания.','sunny','moderate','Поставьте на открытом воздухе в светлое место; в комнате постоянное содержание не планируйте.','Поливайте после лёгкого подсыхания поверхности субстрата, не допуская полного пересыхания корневого кома.'),
  (63,'Бонсай Котонеастер (Кизильник)','Cotoneaster','Кизильник, сформированный в миниатюрное дерево.','Кизильники ценят за мелкую листву и способность переносить формировку. У разных видов листва бывает вечнозелёной или листопадной; цветение и ягоды у конкретного экземпляра не гарантированы.','Выберите для бонсая место на открытом воздухе с солнцем или лёгкой полутенью. Поливайте после подсыхания поверхности грунта, не оставляя корни в воде; зимой защищайте корни в маленьком контейнере от сильного промерзания.','sunny','moderate','Выберите для бонсая место на открытом воздухе с солнцем или лёгкой полутенью.','Поливайте после подсыхания поверхности грунта, не оставляя корни в воде; зимой защищайте корни в маленьком контейнере от сильного промерзания.'),
  (64,'Бонсай Лжелиственница','Pseudolarix amabilis','Листопадный хвойный бонсай из псевдолиственницы.','Псевдолиственница имеет мягкую хвою, которая осенью желтеет и опадает. Kew принимает название Pseudolarix amabilis; лжелиственница нуждается в сезонном покое.','Поставьте на открытом воздухе в светлое место. Поливайте, когда поверхность субстрата начинает подсыхать, не допуская длительного пересыхания маленького горшка; зимой поливайте реже и защищайте контейнер от сильного промерзания.','sunny','frequent','Поставьте на открытом воздухе в светлое место.','Поливайте, когда поверхность субстрата начинает подсыхать, не допуская длительного пересыхания маленького горшка; зимой поливайте реже и защищайте контейнер от сильного промерзания.'),
  (70,'Бонсай Можжевельник','Juniperus','Вечнозелёный можжевельник, сформированный как бонсай.','Можжевельник сохраняет хвою круглый год. Его точный вид и сорт без маркировки не определяются, поэтому цвет и форма хвои могут отличаться от иллюстраций.','Держите на открытом воздухе на солнце. Поливайте после подсыхания поверхности хорошо дренированного субстрата, не оставляя воду в поддоне. Зимой защищайте корни небольшого контейнера от сильного промерзания.','sunny','moderate','Держите на открытом воздухе на солнце.','Поливайте после подсыхания поверхности хорошо дренированного субстрата, не оставляя воду в поддоне.'),
  (75,'Бонсай Пираканта','Pyracantha','Пираканта в форме бонсая с плотной мелкой листвой.','Пираканта — колючий кустарник, который может цвести и образовывать яркие плоды. У этого экземпляра вид и сорт не указаны; плодоношение зависит от условий и формировки.','Держите на открытом воздухе на солнце или в лёгкой полутени. Поливайте после начала подсыхания поверхности грунта, не заливая корни; маленький горшок проверяйте чаще в жару. Зимой защищайте корни в контейнере.','sunny','moderate','Держите на открытом воздухе на солнце или в лёгкой полутени.','Поливайте после начала подсыхания поверхности грунта, не заливая корни; маленький горшок проверяйте чаще в жару.'),
  (76,'Бонсай Подокарпус','Podocarpus','Вечнозелёный бонсай из подокарпуса.','Подокарпусы образуют плотную крону с узкими кожистыми листьями. Точный вид по названию этого товара не установлен.','Поставьте в яркий рассеянный свет, летом можно вынести в защищённое место. Поливайте после лёгкого подсыхания поверхности грунта без застоя воды; зимой берегите от холодного ветра и промерзания контейнера.','diffused','moderate','Поставьте в яркий рассеянный свет, летом можно вынести в защищённое место.','Поливайте после лёгкого подсыхания поверхности грунта без застоя воды; зимой берегите от холодного ветра и промерзания контейнера.'),
  (79,'Бонсай Сагереция чайная','Sageretia thea','Сагереция чайная — миниатюрное деревце с мелкими листьями.','Сагереция чайная, также известная как Sageretia theezans, выращивается как бонсай с тонкими побегами и мелкой листвой. Название вида подтверждено RHS.','Выберите яркий рассеянный свет и тепло, защищайте от холодных сквозняков. Поливайте после лёгкого подсыхания поверхности субстрата, не пересушивая весь маленький горшок; обеспечьте свободный сток воды.','diffused','frequent','Выберите яркий рассеянный свет и тепло, защищайте от холодных сквозняков.','Поливайте после лёгкого подсыхания поверхности субстрата, не пересушивая весь маленький горшок; обеспечьте свободный сток воды.'),
  (81,'Бонсай Самшит прямой','Buxus','Самшит в форме прямостоячего бонсая.','Самшиты — вечнозелёные кустарники с мелкими листьями, хорошо переносящие стрижку. «Прямой» описывает форму бонсая, а не отдельный ботанический вид.','Держите на открытом воздухе на солнце или в лёгкой полутени. Поливайте после подсыхания поверхности субстрата, не оставляя корни в воде; зимой защитите маленький контейнер от сильного промерзания.','sunny','moderate','Держите на открытом воздухе на солнце или в лёгкой полутени.','Поливайте после подсыхания поверхности субстрата, не оставляя корни в воде; зимой защитите маленький контейнер от сильного промерзания.'),
  (82,'Бонсай Самшит Харланда','Buxus harlandii','Самшит Харланда, сформированный как бонсай.','Buxus harlandii — вечнозелёный самшит с небольшой плотной листвой. В форме бонсая его крону поддерживают аккуратной регулярной обрезкой.','Выберите светлое место с защитой от резкого полуденного солнца. Поливайте после начала подсыхания поверхности субстрата, не позволяя маленькому горшку надолго пересохнуть; зимой берегите корни от промерзания.','diffused','moderate','Выберите светлое место с защитой от резкого полуденного солнца.','Поливайте после начала подсыхания поверхности субстрата, не позволяя маленькому горшку надолго пересохнуть; зимой берегите корни от промерзания.'),
  (134,'Ливистона','Livistona','Пальма ливистона с веерными листьями.','Ливистоны — пальмы с крупными рассечёнными веерными листьями. Точный вид растения в названии товара не указан.','Поставьте в яркий рассеянный свет и берегите от холодных сквозняков. Во время роста поливайте после лёгкого подсыхания поверхности грунта; зимой полив сократите и не оставляйте воду в поддоне.','diffused','moderate','Поставьте в яркий рассеянный свет и берегите от холодных сквозняков.','Во время роста поливайте после лёгкого подсыхания поверхности грунта; зимой полив сократите и не оставляйте воду в поддоне.'),
  (140,'Микросорум Крокодилус','Microsorum musifolium ''Crocodyllus''','Папоротник с кожистыми листьями и рисунком жилок, напоминающим кожу крокодила.','Микросорум Crocodyllus — эпифитный папоротник с длинными цельными вайями. Молодые листья ярко-зелёные, а рельеф жилок становится заметнее с возрастом.','Поставьте в яркий рассеянный свет без прямого солнца и холодных сквозняков. Поливайте после лёгкого подсыхания поверхности рыхлого субстрата, поддерживайте влажность воздуха и не оставляйте горшок в воде.','diffused','moderate','Поставьте в яркий рассеянный свет без прямого солнца и холодных сквозняков.','Поливайте после лёгкого подсыхания поверхности рыхлого субстрата, поддерживайте влажность воздуха и не оставляйте горшок в воде.'),
  (188,'Тилландсия','Tillandsia','Воздушное растение, которое обычно выращивают без почвы.','Тилландсии закрепляются на опоре корнями и получают влагу через листья. Вид конкретного экземпляра не указан; потребность в воде может различаться.','Дайте яркий рассеянный свет и хорошее движение воздуха. Поливайте мягкой водой: кратко погружайте растение, затем дайте полностью просохнуть и не оставляйте воду в розетке. В прохладе поливайте реже.','diffused','frequent','Дайте яркий рассеянный свет и хорошее движение воздуха.','Поливайте мягкой водой: кратко погружайте растение, затем дайте полностью просохнуть и не оставляйте воду в розетке.'),
  (863,'Амариллис D12','Hippeastrum','Комнатное луковичное растение, продаваемое под названием «амариллис».','Комнатные «амариллисы» обычно относятся к гиппеаструмам. Точный сорт и окраска цветка этого экземпляра не установлены; диаметр горшка D12 сохранён как характеристика варианта.','Поставьте в яркий рассеянный свет. После появления листьев поливайте регулярно, когда поверхность грунта слегка подсохнет, не оставляя воду в поддоне. После цветения сохраните листья; на период покоя полив сокращайте.','diffused','moderate','Поставьте в яркий рассеянный свет.','После появления листьев поливайте регулярно, когда поверхность грунта слегка подсохнет, не оставляя воду в поддоне.');
UPDATE products AS p SET
 latin_name = CASE WHEN BTRIM(COALESCE(p.latin_name,'')) = '' THEN c.latin ELSE p.latin_name END,
 short_description = CASE WHEN BTRIM(COALESCE(p.short_description,'')) = '' THEN c.short_text ELSE p.short_description END,
 description = CASE WHEN BTRIM(COALESCE(p.description,'')) = '' THEN c.full_text ELSE p.description END,
 care_instructions = CASE WHEN BTRIM(COALESCE(p.care_instructions,'')) = '' THEN c.care_text ELSE p.care_instructions END,
 light_level = CASE WHEN BTRIM(COALESCE(p.light_level,'')) = '' THEN c.light ELSE p.light_level END,
 watering = CASE WHEN BTRIM(COALESCE(p.watering,'')) = '' THEN c.watering ELSE p.watering END,
 plant_passport = COALESCE(p.plant_passport,'{}'::jsonb)
  || CASE WHEN BTRIM(COALESCE(p.plant_passport->>'lighting','')) = '' THEN jsonb_build_object('lighting',c.guide_light) ELSE '{}'::jsonb END
  || CASE WHEN BTRIM(COALESCE(p.plant_passport->>'watering','')) = '' THEN jsonb_build_object('watering',c.guide_water) ELSE '{}'::jsonb END,
 updated_at = CURRENT_TIMESTAMP
FROM curated_plant_content_fourth AS c
WHERE p.product_code = c.product_code AND p.catalog_section = 'plants' AND p.name = c.expected_name
 AND (BTRIM(COALESCE(p.latin_name,''))='' OR BTRIM(COALESCE(p.short_description,''))='' OR BTRIM(COALESCE(p.description,''))='' OR BTRIM(COALESCE(p.care_instructions,''))=''
  OR BTRIM(COALESCE(p.light_level,''))='' OR BTRIM(COALESCE(p.watering,''))='' OR BTRIM(COALESCE(p.plant_passport->>'lighting',''))='' OR BTRIM(COALESCE(p.plant_passport->>'watering',''))='');
